 return o

def transform(grid):
 h,w=len(grid),len(grid[0])
 if h==12 and w==12:
  t=[list(r) for r in zip(*grid)]
  return [[max(grid[i][j],t[i][j]) for j in range(w)] for i in range(h)]
 return [r[::-1] for r in grid[::-1]]
